/bin/bash -lc "node --input-type=module <<'EOF'
const cases = [
  ['/products/lamp?currency=EUR', 'Brass lamp', 'EUR 110.40', 'Stone vase'],
  ['/products/lamp?currency=USD', 'Brass lamp', 'USD 120.00', 'Stone vase'],
  ['/products/vase?currency=EUR', 'Stone vase', 'EUR 73.60', 'Brass lamp'],
  ['/products/lamp?currency=EUR', 'Brass lamp', 'EUR 110.40', 'Stone vase'],
]
for (const [path, name, price, related] of cases) {
  const start = performance.now()
  const response = await fetch('http://localhost:3100' + path, { headers: { 'Accept-Encoding': 'identity' } })
  const reader = response.body.getReader()
  const decoder = new TextDecoder()
  let html = ''
  const seen = {}
  while (true) {
    const { done, value } = await reader.read()
    if (done) break
    html += decoder.decode(value, { stream: true })
    for (const [label, needle] of [
      ['shop frame', 'Signal Shop collection'],
      ['product fallback', 'Loading product details'],
      ['product', '<h1>' + name + '</h1>'],
      ['price', '<p>' + price + '</p>'],
      ['related fallback', 'Finding related products'],
      ['related', '>' + related + '</a>'],
    ]) {
      if (seen[label] === undefined && html.includes(needle)) seen[label] = Math.round(performance.now() - start)
    }
  }
  if (response.status "'!== 200 || !html.includes('"'<h1>' + name + '</h1>') || "'!html.includes('"'<p>' + price + '</p>') || "'!html.includes('"'>' + related + '</a>')) {
    throw new Error('Unexpected response for ' + path + ': ' + response.status)
  }
  console.log(path, response.status, seen)
}
EOF"

